const DEFAULT_DATA_DIR: &str = "/opt/vdb-data";

#[derive(Deserialize)]
struct QueryVector {
    vector: Vec<f32>,
}

#[derive(Deserialize)]
struct GroundTruthEntry {
    query_id: usize,
    neighbors: Vec<u64>,
}

