        _mm256_loadu_ps(q_ptr.add(24)),
        _mm256_loadu_ps(q_ptr.add(32)),
        _mm256_loadu_ps(q_ptr.add(40)),
        _mm256_loadu_ps(q_ptr.add(48)),
        _mm256_loadu_ps(q_ptr.add(56)),
        _mm256_loadu_ps(q_ptr.add(64)),
        _mm256_loadu_ps(q_ptr.add(72)),
        _mm256_loadu_ps(q_ptr.add(80)),
        _mm256_loadu_ps(q_ptr.add(88)),
        _mm256_loadu_ps(q_ptr.add(96)),
        _mm256_loadu_ps(q_ptr.add(104)),
        _mm256_loadu_ps(q_ptr.add(112)),
        _mm256_loadu_ps(q_ptr.add(120)),
    ];
    let v_ptr = vectors_flat.as_ptr() as *const u16;

    for (out_idx, &position) in positions.iter().enumerate() {
        let base = v_ptr.add(position * DIM);
        let mut sum = _mm256_setzero_ps();

        for (chunk_idx, &q) in q_chunks.iter().enumerate() {
            let v = _mm_loadu_si128(base.add(chunk_idx * 8) as *const __m128i);
            let vf = _mm256_cvtph_ps(v);
            let delta = _mm256_sub_ps(q, vf);
            sum = _mm256_add_ps(sum, _mm256_mul_ps(delta, delta));
        }

        distances[out_idx] = horizontal_sum_m256(sum);
    }
}

#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "avx2")]
unsafe fn l2_squared_u8_avx2(query: &[u8; DIM], vector: &[u8]) -> u32 {
    use std::arch::x86_64::*;

    let q_ptr = query.as_ptr();
    let v_ptr = vector.as_ptr();
    let mut sum = _mm256_setzero_si256();

    for offset in (0..DIM).step_by(16) {
        let q = _mm_loadu_si128(q_ptr.add(offset) as *const __m128i);
        let v = _mm_loadu_si128(v_ptr.add(offset) as *const __m128i);
        let q16 = _mm256_cvtepu8_epi16(q);
        let v16 = _mm256_cvtepu8_epi16(v);
        let delta = _mm256_sub_epi16(q16, v16);
        let squared = _mm256_madd_epi16(delta, delta);
        sum = _mm256_add_epi32(sum, squared);
    }

    horizontal_sum_m256i_u32(sum)
}

#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "avx2")]
unsafe fn l2_distance_batch_u8_avx2(
    query: &[u8; DIM],
    vectors_flat: &[u8],
    n_vectors: usize,
    distances: &mut [u32],
) {
    use std::arch::x86_64::*;

    let q_ptr = query.as_ptr();
    let q_chunks = [
        _mm256_cvtepu8_epi16(_mm_loadu_si128(q_ptr as *const __m128i)),
        _mm256_cvtepu8_epi16(_mm_loadu_si128(q_ptr.add(16) as *const __m128i)),
        _mm256_cvtepu8_epi16(_mm_loadu_si128(q_ptr.add(32) as *const __m128i)),
        _mm256_cvtepu8_epi16(_mm_loadu_si128(q_ptr.add(48) as *const __m128i)),
        _mm256_cvtepu8_epi16(_mm_loadu_si128(q_ptr.add(64) as *const __m128i)),
        _mm256_cvtepu8_epi16(_mm_loadu_si128(q_ptr.add(80) as *const __m128i)),
        _mm256_cvtepu8_epi16(_mm_loadu_si128(q_ptr.add(96) as *const __m128i)),
        _mm256_cvtepu8_epi16(_mm_loadu_si128(q_ptr.add(112) as *const __m128i)),
    ];
    let v_ptr = vectors_flat.as_ptr();

    for idx in 0..n_vectors {
        let base = v_ptr.add(idx * DIM);
        let mut sum = _mm256_setzero_si256();

        for (chunk_idx, &q16) in q_chunks.iter().enumerate() {
            let v = _mm_loadu_si128(base.add(chunk_idx * 16) as *const __m128i);
            let v16 = _mm256_cvtepu8_epi16(v);
            let delta = _mm256_sub_epi16(q16, v16);
            let squared = _mm256_madd_epi16(delta, delta);
            sum = _mm256_add_epi32(sum, squared);
        }

        distances[idx] = horizontal_sum_m256i_u32(sum);
    }
}

